async function newItem(kind) { let color = "#000000"; if (kind === "color") { color = prompt("Matte color (#RRGGBB)", "#E8631C"); if (!color) return; } const dur = kind === "counting_leader" ? 11 : (S.prefs.still || 5); await api.json("POST", "/api/media/synthetic", { kind, color, duration: dur, width: S.seq.width, height: S.seq.height, actor: "human" }); status(`Created ${kind.replace("_", " ")} item`); }
async function renderReplace() { const sel = CR.selectedClips().filter(x => x.c.media_id || x.c.sequence_id || x.c.title || x.c.graphic); if (sel.length !== 1) { status("Select one clip to render and replace."); return; } if (!confirm("Render this clip with all its effects to a new media file and replace it in the timeline?")) return; status("Rendering clip…"); const r = await fetch("/api/render_replace", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sequence: S.seq.id, clip_id: sel[0].c.id, actor: "human" }) }); const j = await r.json(); status(r.ok ? "Rendered and replaced." : (j.detail || "render failed"), r.ok ? "" : "err"); if (r.ok) await CR.loadProject(true); }
function replaceFromBin() { const sel = CR.selectedClips().filter(x => x.c.media_id); const mid = [...S.binSel][0]; if (sel.length !== 1 || !mid) { status("Select one timeline clip and one bin item."); return; } const { c, tr } = sel[0]; const m = S.proj.media[mid]; const d = clipDur(c); if (!m.is_image && m.duration < d) { status("Bin clip is shorter than the timeline clip."); return; } applyOps([{ op: "set_clip", sequence: S.seq.id, track: tr.id, clip: { id: c.id, media_id: mid, in_: 0, out: d * (c.speed || 1), time_remap: null, hold: false } }], "replace", `replace with ${m.name}`); }
