function removeUnused() { const used = new Set(); for (const sq of S.proj.sequences) for (const t of sq.tracks) for (const c of t.clips) if (c.media_id) { used.add(c.media_id); const m = S.proj.media[c.media_id]; if (m && m.subclip_of) used.add(m.subclip_of); } const unused = Object.keys(S.proj.media).filter(id => !used.has(id)); if (!unused.length) { status("No unused media."); return; } if (!confirm(`Remove ${unused.length} unused item(s) from the project? (files are not deleted)`)) return; applyOps(unused.map(id => ({ op: "remove", path: `/media/${id}` })), "remove_unused", `remove ${unused.length} unused`); }
async function renderInOut() { const a = S.seq.in_point, b = S.seq.out_point; if (a == null || b == null || b <= a) { status("Set sequence In and Out first."); return; } status("Rendering preview In → Out…"); const j = await api.json("POST", "/api/render", { sequence: S.seq.id, preset: { crf: 20, x264_preset: "veryfast", range: true }, name: `preview_${S.seq.id}`, actor: "human" }); const poll = async () => { const st = await api.get("/api/render/" + j.id); if (st.status === "running" || st.status === "queued") { setTimeout(poll, 1500); return; } if (st.status === "done") { CR.pv.file = st.out + "?v=" + Date.now(); CR.pv.range = [a, b]; S.previewMode = true; status("Preview rendered — playback inside In–Out uses the rendered file (View → Play Rendered Preview to toggle)."); CR.renderProgram(); } else status("Preview render failed: " + (st.error || ""), "err"); }; poll(); }
async function remixDialog() { const sel = CR.selectedClips().filter(x => x.c.media_id && S.proj.media[x.c.media_id].has_audio && x.tr.kind === "audio"); if (sel.length !== 1) { status("Select one music clip on an audio track."); return; } const { c, tr } = sel[0]; const cur = clipDur(c); const v = prompt(`Remix "${S.proj.media[c.media_id].name}" to duration (seconds) — currently ${cur.toFixed(1)} s`, String(Math.round(cur))); if (!v) return; const target = parseFloat(v); if (!(target > 1)) return; status("Analyzing tempo…");
  const r = await api.json("POST", "/api/audio/remix", { media_id: c.media_id, target }); const ops = [{ op: "remove_clip", sequence: S.seq.id, track: tr.id, clip_id: c.id }]; let t = c.start; r.segments.forEach((sg, i) => { ops.push({ op: "set_clip", sequence: S.seq.id, track: tr.id, clip: { ...deep(c), id: CR.uid(), start: +t.toFixed(4), in_: sg.in, out: sg.out, audio_transition_in: i ? { type: "constant_power", duration: 0.4 } : (c.audio_transition_in || null), audio_transition_out: i < r.segments.length - 1 ? { type: "constant_power", duration: 0.4 } : (c.audio_transition_out || null), note: `remix segment ${i + 1}/${r.segments.length} · ${r.bpm} BPM, ${r.phrase}s phrases` } }); t += sg.out - sg.in; });
  applyOps(ops, "remix", `remix to ${target}s (${r.bpm} BPM) → ${r.achieved}s`); status(`Remixed: ${r.segments.length} segment(s), ${r.bpm} BPM, achieved ${r.achieved}s`); }
function timeTuner() { const cur = CR.seqDur(); const v = prompt(`Time Tuner — fit the sequence to a duration (seconds). Current ${cur.toFixed(2)} s. Premiere-style: tiny uniform speed changes on every clip, cuts kept in order; up to ±10% is invisible.`, String(Math.round(cur))); if (!v) return; const target = parseFloat(v); if (!(target > 1) || Math.abs(target - cur) < 0.01) return; const f = cur / target; if (f < 0.7 || f > 1.4) { if (!confirm(`This needs ${((f - 1) * 100).toFixed(0)}% speed change — beyond Time Tuner's invisible range. Apply anyway?`)) return; }
  const si = S.proj.sequences.indexOf(S.seq); const ops = []; for (const tr of S.seq.tracks) for (const c of tr.clips) { const patch = { id: c.id, start: +(c.start / f).toFixed(4) }; if (c.media_id && !(S.proj.media[c.media_id] || {}).is_image && !c.hold && !c.time_remap) patch.speed = +((c.speed || 1) * f).toFixed(4); else if (!c.media_id || (S.proj.media[c.media_id] || {}).is_image) patch.out = +(c.in_ + (c.out - c.in_) / f).toFixed(4); ops.push({ op: "set_clip", sequence: S.seq.id, track: tr.id, clip: patch }); }
  ops.push({ op: "set", path: `/sequences/${si}/markers`, value: (S.seq.markers || []).map(m => ({ ...m, time: +(m.time / f).toFixed(4) })) }); ops.push({ op: "set", path: `/sequences/${si}/captions`, value: (S.seq.captions || []).map(cp => ({ ...cp, start: +(cp.start / f).toFixed(3), end: +(cp.end / f).toFixed(3) })) }); applyOps(ops, "time_tuner", `time tuner ${cur.toFixed(2)}s → ${target}s (${((f - 1) * 100).toFixed(1)}% speed)`); }
